pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testFuzz_property(address initializer) public {
        vm.assume(initializer != address(0));
        vm.prank(initializer);
        c.initialize();
        address ownerResult = c.owner();
        assertTrue(ownerResult == initializer);
    }
